create or replace function public.cpcm_commission_from_approved_payment() returns trigger language plpgsql security definer set search_path=public as $$ declare led public.payments_ledger%rowtype; rate numeric; earned numeric; begin if new.ledger_id is null or new.reviewed_by_email is null or lower(coalesce(new.status,'')) not in ('approved','completed','paid') then return new; end if; if exists(select 1 from public.employee_commission_earnings where approval_request_id=new.id) then return new; end if; select * into led from public.payments_ledger where id=new.ledger_id; if not found or lower(coalesce(led.status,'')) not in ('completed','paid','settled','processed','success') or lower(coalesce(led.gateway_provider,''))<>'nmi' or coalesce(led.gateway_transaction_id,'')='' then return new; end if; select commission_rate into rate from public.app_users where lower(email)=lower(new.requested_by_email) and coalesce(is_active,true)=true; if rate is null then return new; end if; earned:=round(coalesce(led.amount,led.payment_amount,0)*rate/100,2); insert into public.employee_commission_earnings(ledger_id,approval_request_id,employee_email,gross_amount,commission_rate,earned_amount,status,approved_by_email,approved_at) values(led.id,new.id,lower(new.requested_by_email),coalesce(led.amount,led.payment_amount,0),rate,earned,'Earned',lower(new.reviewed_by_email),coalesce(new.reviewed_at,led.paid_at,led.created_at,now())) on conflict do nothing; return new; end $$;
drop trigger if exists trg_commission_from_approved_payment on public.payment_approval_requests; create trigger trg_commission_from_approved_payment after insert or update of status,ledger_id,reviewed_by_email,reviewed_at on public.payment_approval_requests for each row execute function public.cpcm_commission_from_approved_payment(); revoke all on function public.cpcm_commission_from_approved_payment() from public,anon,authenticated;
